WITH unpivoted AS (SELECT id, channel, metric_name, metric_value FROM (SELECT id, channel, amount, shipping_fee, discount FROM orders) src UNPIVOT (metric_value FOR metric_name IN (amount, shipping_fee, discount))) SELECT CASE WHEN metric_value >= 86 THEN 'LARGE' ELSE 'SMALL' END AS metric_value_tier, metric_name, ROUND(AVG(metric_value), 2) AS avg_metric_value, COUNT_IF(metric_name = 'shipping_fee') AS shipping_fee_events, COUNT(DISTINCT id) AS distinct_ids, RANK() OVER (PARTITION BY CASE WHEN metric_value >= 86 THEN 'LARGE' ELSE 'SMALL' END ORDER BY COUNT_IF(metric_name = 'shipping_fee') DESC) AS shipping_fee_events_rank FROM unpivoted GROUP BY CASE WHEN metric_value >= 86 THEN 'LARGE' ELSE 'SMALL' END, metric_name ORDER BY metric_name DESC NULLS FIRST
